<?php require __DIR__.'/../layouts/header.php';?><h1>Secure Comment Module</h1><form class="panel" method="post"><input type="hidden" name="_csrf" value="<?=SecurityHelper::e($csrf)?>"><label>Name</label><input name="name" maxlength="100" required><label>Comment</label><textarea name="body" maxlength="2000" required></textarea><button>Post Comment</button></form><h2>Comments</h2><?php foreach($comments as $c):?><article class="panel"><b><?=SecurityHelper::e($c['name'])?></b><p><?=nl2br(SecurityHelper::e($c['body']))?></p></article><?php endforeach;?><?php require __DIR__.'/../layouts/footer.php';?>